import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    monasteries = set()
    for _ in range(m):
        monasteries.add(int(next(iterator)))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    non_monastery_towns = []
    for i in range(1, n + 1):
        if i not in monasteries:
            non_monastery_towns.append(i)

    def bfs(start_nodes):
        dist = [-1] * (n + 1)
        q = deque()
        for s in start_nodes:
            dist[s] = 0
            q.append(s)

        while q:
            u = q.popleft()
            for v, w in adj[u]:
                new_dist = dist[u] + w
                if dist[v] == -1 or new_dist < dist[v]:
                    dist[v] = new_dist
                    q.append(v)
        return dist

    dist_to_nearest_monastery = bfs(list(monasteries))

    max_unhappy = 0
    ways = 0

    for town in non_monastery_towns:
        current_unhappy = 0

        removed = {town}
        component_monasteries = []
        visited = [False] * (n + 1)
        q = deque()

        for neighbor, _ in adj[town]:
            if not visited[neighbor]:
                q.append(neighbor)
                visited[neighbor] = True
                component = []
                comp_q = deque([neighbor])
                comp_visited = {neighbor}

                while comp_q:
                    curr = comp_q.popleft()
                    if curr in monasteries:
                        component.append(curr)
                    for nxt, _ in adj[curr]:
                        if nxt != town and nxt not in comp_visited:
                            comp_visited.add(nxt)
                            comp_q.append(nxt)

                if component:
                    component_monasteries.extend(component)

        if not component_monasteries:
            continue

        farthest_in_component = []
        max_dist_in_comp = -1

        for mon in component_monasteries:
            d = dist_to_nearest_monastery[mon]
            if d > max_dist_in_comp:
                max_dist_in_comp = d
                farthest_in_component = [mon]
            elif d == max_dist_in_comp:
                farthest_in_component.append(mon)

        if farthest_in_component:
            reachable_farthest = []
            for mon in farthest_in_component:
                if mon in component_monasteries:
                    reachable_farthest.append(mon)

            if len(reachable_farthest) < len(farthest_in_component):
                current_unhappy += 1

        if current_unhappy > max_unhappy:
            max_unhappy = current_unhappy
            ways = 1
        elif current_unhappy == max_unhappy:
            ways += 1

    print(f"{max_unhappy} {ways}")

if __name__ == "__main__":
    solve()
